import hmac
import hashlib
import json
import base64
import time
import os
import secrets
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs

# Permission bits
PERM_READ = 0x01
PERM_WRITE = 0x02
PERM_DELETE = 0x04
PERM_ADMIN = 0x08
PERM_SUPER = 0x10

# Only admin+super can access management endpoints
MANAGEMENT_REQUIRED = PERM_ADMIN | PERM_SUPER  # 0x18

# Server signing key - generated at startup
SERVER_KEY = os.urandom(32)

# User database with permission levels
USER_DB = {
    "alice": {"password_hash": hashlib.sha256(b"alice_secret_pw").hexdigest(), "permissions": PERM_READ | PERM_WRITE},
    "bob": {"password_hash": hashlib.sha256(b"bob_secret_pw").hexdigest(), "permissions": PERM_READ},
    "admin": {"password_hash": hashlib.sha256(b"admin_secret_pw").hexdigest(), "permissions": PERM_READ | PERM_WRITE | PERM_DELETE | PERM_ADMIN | PERM_SUPER},
}

def b64url_encode(data):
    if isinstance(data, str):
        data = data.encode('utf-8')
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')

def b64url_decode(s):
    s = s + '=' * (4 - len(s) % 4)
    return base64.urlsafe_b64decode(s)

def create_token(username, permissions):
    """Create a signed token with user claims."""
    header = {"alg": "HS256", "typ": "JWT"}
    payload = {
        "sub": username,
        "perms": permissions,
        "iat": int(time.time()),
        "exp": int(time.time()) + 3600
    }
    header_b64 = b64url_encode(json.dumps(header, separators=(',', ':')))
    payload_b64 = b64url_encode(json.dumps(payload, separators=(',', ':')))
    signing_input = f"{header_b64}.{payload_b64}".encode('ascii')
    signature = hmac.new(SERVER_KEY, signing_input, hashlib.sha256).digest()
    sig_b64 = b64url_encode(signature)
    return f"{header_b64}.{payload_b64}.{sig_b64}"

def verify_token(token):
    """Verify token signature and return claims."""
    try:
        parts = token.split('.')
        if len(parts) != 3:
            return None, "malformed token"

        header_b64, payload_b64, sig_b64 = parts

        # Verify header
        header = json.loads(b64url_decode(header_b64))
        if header.get('alg') != 'HS256' or header.get('typ') != 'JWT':
            return None, "invalid header"

        # Verify signature
        signing_input = f"{header_b64}.{payload_b64}".encode('ascii')
        expected_sig = hmac.new(SERVER_KEY, signing_input, hashlib.sha256).digest()
        actual_sig = b64url_decode(sig_b64)

        if not hmac.compare_digest(expected_sig, actual_sig):
            return None, "invalid signature"

        # Parse and validate claims
        claims = json.loads(b64url_decode(payload_b64))

        # Check expiration
        exp = claims.get('exp')
        if exp is not None and time.time() > exp:
            return None, "token expired"

        return claims, None
    except Exception:
        return None, "token verification failed"

def extract_permissions(claims):
    """Extract permission bitmask from verified token claims.

    The perms field stores the user's permission bitmask as an integer.
    We validate it's a proper integer before using it in bitwise operations.
    """
    perms_raw = claims.get('perms')
    if perms_raw is None:
        return 0
    # Ensure it's an integer (JSON numbers are parsed as int/float)
    if isinstance(perms_raw, float):
        perms_raw = int(perms_raw)
    if not isinstance(perms_raw, int):
        return 0
    return perms_raw

def check_permission(user_perms, required_perms):
    """Check if user has all required permission bits set.

    Uses bitwise AND to verify each required bit is present
    in the user's permission mask.
    """
    return (user_perms & required_perms) == required_perms

def authenticate(username, password):
    """Authenticate user and return a signed token."""
    if not username or not password:
        return None
    if not isinstance(username, str) or not isinstance(password, str):
        return None

    user = USER_DB.get(username)
    if user is None:
        # Constant-time comparison against dummy to prevent timing leak
        hmac.compare_digest(
            hashlib.sha256(password.encode()).hexdigest(),
            hashlib.sha256(b"dummy").hexdigest()
        )
        return None

    pw_hash = hashlib.sha256(password.encode()).hexdigest()
    if not hmac.compare_digest(pw_hash, user["password_hash"]):
        return None

    return create_token(username, user["permissions"])

class RequestHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        path = urlparse(self.path).path

        if path == '/login':
            self._handle_login()
        elif path == '/management/users':
            self._handle_management()
        elif path == '/api/data':
            self._handle_data_access()
        else:
            self._send_response(404, {"error": "not found"})

    def do_GET(self):
        path = urlparse(self.path).path
        if path == '/api/profile':
            self._handle_profile()
        else:
            self._send_response(404, {"error": "not found"})

    def _get_token_claims(self):
        """Extract and verify token from Authorization header."""
        auth_header = self.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return None, "missing or invalid authorization header"
        token = auth_header[7:]
        return verify_token(token)

    def _handle_login(self):
        try:
            content_length = int(self.headers.get('Content-Length', 0))
            if content_length > 4096:
                self._send_response(413, {"error": "payload too large"})
                return
            body = self.rfile.read(content_length)
            data = json.loads(body)
            username = data.get('username')
            password = data.get('password')
            token = authenticate(username, password)
            if token:
                self._send_response(200, {"token": token})
            else:
                self._send_response(401, {"error": "invalid credentials"})
        except (json.JSONDecodeError, ValueError):
            self._send_response(400, {"error": "invalid request"})

    def _handle_management(self):
        """Management endpoint - requires ADMIN + SUPER permissions."""
        claims, err = self._get_token_claims()
        if err:
            self._send_response(401, {"error": err})
            return

        user_perms = extract_permissions(claims)

        if not check_permission(user_perms, MANAGEMENT_REQUIRED):
            self._send_response(403, {"error": "insufficient permissions"})
            return

        # Management action: list users
        user_list = [{"username": u, "permissions": d["permissions"]} for u, d in USER_DB.items()]
        self._send_response(200, {"users": user_list})

    def _handle_data_access(self):
        """Data endpoint - requires READ permission."""
        claims, err = self._get_token_claims()
        if err:
            self._send_response(401, {"error": err})
            return

        user_perms = extract_permissions(claims)

        if not check_permission(user_perms, PERM_READ):
            self._send_response(403, {"error": "insufficient permissions"})
            return

        self._send_response(200, {"data": "sensitive information", "user": claims.get('sub')})

    def _handle_profile(self):
        """Profile endpoint - any authenticated user."""
        claims, err = self._get_token_claims()
        if err:
            self._send_response(401, {"error": err})
            return

        self._send_response(200, {"sub": claims.get('sub'), "permissions": claims.get('perms')})

    def _send_response(self, status, body):
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.end_headers()
        self.wfile.write(json.dumps(body).encode('utf-8'))

    def log_message(self, format, *args):
        pass  # Suppress default logging

if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8080), RequestHandler)
    server.serve_forever()
